// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * The AGM (Atserias–Grohe–Marx) bound on the number of rows a join can emit, computed from a fractional edge cover.
 * <p>
 * <b>What this is, in plain terms.</b> Model the join as a hypergraph: each <em>variable</em> is a vertex, and each
 * triple pattern is a <em>hyperedge</em> — the set of vertices for the variables that pattern mentions. ("Hyper" only
 * means an edge may touch more than two vertices.) A <em>fractional edge cover</em> assigns each edge a weight
 * {@code x_e >= 0} such that, for every vertex, the weights of the edges containing it sum to at least 1. For any such
 * assignment, AGM says the join emits at most {@code product of |R_e|^x_e} rows. Minimising that product over all
 * covers gives the tightest bound.
 * <p>
 * <b>Why the engine needs it.</b> A worst-case-optimal join runs in time proportional to this bound, whereas any plan
 * built from pairwise joins can be forced to materialize an intermediate result far larger than it. That gap is the
 * entire reason {@link LmdbNativeLeapfrogJoin} exists, and it cannot be expressed by multiplying per-pattern
 * cardinalities: on a triangle the product is {@code N^3} while the bound is {@code N^1.5}. Costing the leapfrog with a
 * product — which is what its dead {@code estimate} override used to return — would price it as the most expensive
 * strategy everywhere and guarantee it was never chosen.
 * <p>
 * <b>Soundness does not depend on optimality.</b> AGM holds for <em>any</em> fractional cover, not only the minimising
 * one. So when the solver hits its iteration cap or the numbers misbehave, this falls back to a greedy integral cover
 * and still returns a valid upper bound — merely a looser one. There is no configuration in which it reports a bound
 * below the true output size.
 */
@Experimental
final class LmdbNativeAgmBound {

	/** A hyperedge: the free variables the pattern binds, and how many rows it holds. */
	record Edge(long vertexMask, double size) {
	}

	/** Bland's-rule simplex is guaranteed to terminate; this only bounds pathological pivot counts. */
	private static final int MAX_PIVOTS = 256;

	private LmdbNativeAgmBound() {
	}

	/**
	 * Upper bound on the rows the join over {@code edges} can emit, or {@link Double#NaN} when it cannot be computed —
	 * an edge of unknown size, or a variable no edge covers.
	 * <p>
	 * Never returns infinity: "cannot be bounded" is unknown, not infinitely expensive, and the two must not be
	 * confused (see {@link LmdbNativeWork}).
	 */
	static double bound(Edge[] edges, long vertexMask) {
		if (edges == null || edges.length == 0) {
			return vertexMask == 0L ? 1D : Double.NaN;
		}
		for (Edge edge : edges) {
			if (!Double.isFinite(edge.size()) || edge.size() < 0D) {
				return Double.NaN;
			}
		}
		// Every vertex must be coverable, or no fractional cover exists at all.
		long covered = 0L;
		for (Edge edge : edges) {
			covered |= edge.vertexMask();
		}
		if ((vertexMask & ~covered) != 0L) {
			return Double.NaN;
		}
		if (vertexMask == 0L) {
			return 1D;
		}
		// Solve in log space: minimising the product of |R_e|^x_e is minimising sum of x_e * ln|R_e|.
		double logBound = minimumCoverLogWeight(edges, vertexMask);
		if (Double.isNaN(logBound)) {
			return Double.NaN;
		}
		double result = Math.exp(logBound);
		return Double.isFinite(result) ? result : Double.MAX_VALUE;
	}

	/**
	 * The optimal value of the fractional edge cover LP, in log space.
	 * <p>
	 * Solved through the dual, {@code max sum(y_v) subject to sum of y_v over v in e <= c_e, y >= 0} with
	 * {@code c_e = ln(max(1, |R_e|))}. The dual is the convenient side because {@code y = 0} is always feasible, so a
	 * plain simplex needs no phase-one and no big-M; strong duality makes its optimum the primal's.
	 */
	private static double minimumCoverLogWeight(Edge[] edges, long vertexMask) {
		int[] vertices = verticesOf(vertexMask);
		int m = vertices.length;
		int n = edges.length;

		// Tableau rows: one per edge constraint. Columns: m duals, n slacks, RHS.
		int cols = m + n + 1;
		double[][] tableau = new double[n + 1][cols];
		for (int e = 0; e < n; e++) {
			for (int v = 0; v < m; v++) {
				if ((edges[e].vertexMask() & (1L << vertices[v])) != 0L) {
					tableau[e][v] = 1D;
				}
			}
			tableau[e][m + e] = 1D;
			tableau[e][cols - 1] = Math.log(Math.max(1D, edges[e].size()));
		}
		// Objective row holds negated coefficients; simplex pivots while a negative one remains.
		for (int v = 0; v < m; v++) {
			tableau[n][v] = -1D;
		}

		int[] basis = new int[n];
		for (int e = 0; e < n; e++) {
			basis[e] = m + e;
		}

		for (int pivots = 0; pivots < MAX_PIVOTS; pivots++) {
			// Bland's rule: lowest-index improving column, then lowest-index ratio winner. Slower than steepest
			// descent but provably non-cycling, which matters more than speed at these sizes.
			int enter = -1;
			for (int c = 0; c < m + n; c++) {
				if (tableau[n][c] < -1e-9) {
					enter = c;
					break;
				}
			}
			if (enter < 0) {
				return tableau[n][cols - 1];
			}
			int leave = -1;
			double best = Double.POSITIVE_INFINITY;
			for (int r = 0; r < n; r++) {
				if (tableau[r][enter] > 1e-9) {
					double ratio = tableau[r][cols - 1] / tableau[r][enter];
					if (ratio < best - 1e-12 || (Math.abs(ratio - best) <= 1e-12 && (leave < 0
							|| basis[r] < basis[leave]))) {
						best = ratio;
						leave = r;
					}
				}
			}
			if (leave < 0) {
				// Unbounded dual means the primal is infeasible: no cover exists. Fall back to the greedy bound,
				// which is sound whenever one does exist, and to unknown when one does not.
				return greedyCoverLogWeight(edges, vertexMask);
			}
			pivot(tableau, basis, leave, enter, cols, n);
		}
		return greedyCoverLogWeight(edges, vertexMask);
	}

	private static void pivot(double[][] tableau, int[] basis, int leave, int enter, int cols, int n) {
		double factor = tableau[leave][enter];
		for (int c = 0; c < cols; c++) {
			tableau[leave][c] /= factor;
		}
		for (int r = 0; r <= n; r++) {
			if (r == leave) {
				continue;
			}
			double coefficient = tableau[r][enter];
			if (coefficient == 0D) {
				continue;
			}
			for (int c = 0; c < cols; c++) {
				tableau[r][c] -= coefficient * tableau[leave][c];
			}
		}
		basis[leave] = enter;
	}

	/**
	 * A feasible integral cover found greedily: repeatedly take the edge covering the most still-uncovered vertices.
	 * Weight 1 per chosen edge, so the bound is the product of their sizes — sound, and loose by at most a logarithmic
	 * factor in the exponent.
	 */
	private static double greedyCoverLogWeight(Edge[] edges, long vertexMask) {
		long remaining = vertexMask;
		double total = 0D;
		while (remaining != 0L) {
			int bestEdge = -1;
			int bestCovered = 0;
			for (int e = 0; e < edges.length; e++) {
				int covers = Long.bitCount(edges[e].vertexMask() & remaining);
				if (covers > bestCovered) {
					bestCovered = covers;
					bestEdge = e;
				}
			}
			if (bestEdge < 0) {
				return Double.NaN;
			}
			total += Math.log(Math.max(1D, edges[bestEdge].size()));
			remaining &= ~edges[bestEdge].vertexMask();
		}
		return total;
	}

	private static int[] verticesOf(long mask) {
		int[] vertices = new int[Long.bitCount(mask)];
		int index = 0;
		for (int slot = 0; slot < Long.SIZE; slot++) {
			if ((mask & (1L << slot)) != 0L) {
				vertices[index++] = slot;
			}
		}
		return vertices;
	}
}
